targets.expr:
sum by (user,dest_namespace,application) (
  count_over_time(
    {k8s_cluster_name=~"$cluster", k8s_container_name="server"} |= `` | label_format level=detected_level | json | user="argocd", msg =~ `.*initiated sync.*` |= "$filter"
    [$__auto]
  )
)

sum by (user,dest_namespace,application) (
  count_over_time(
    {k8s_cluster_name=~"$cluster", k8s_container_name="server"} |= `` | label_format level=detected_level | json | user!="argocd", msg =~ `.*initiated sync.*` |= "$filter"
    [$__auto]
  )
)

sum by (user,dest_namespace,application) (
  count_over_time(
    {k8s_cluster_name=~"$cluster", k8s_container_name="server"} |= `` | label_format level=detected_level | json | user!="argocd", msg =~ `.*initiated partial sync.*` |= "$filter"
    [$__auto]
  )
)

count(
  count by (email) (
    count_over_time(
      {k8s_cluster_name=~"$cluster", k8s_container_name="server"}
      | json
      | line_format "{{.grpc_request_claims}}"
      | json
      | email!=""
      |= "$filter"
      [1m]
    )
  )
)

sum by (email) (
  count_over_time(
		{k8s_cluster_name=~"$cluster", k8s_container_name="server"} | json | line_format "{{.grpc_request_claims}}" | json | email!="" |= "$filter"
    [$__auto]
  )
)

sum by (grpc_request_content_name) (
  count_over_time(
		{k8s_cluster_name=~"$cluster", k8s_container_name="server"} | json | line_format "{{.grpc_request_claims}}" | json | grpc_request_content_name!="" |="$filter"
    [$__auto]
  )
)

sum by (msg) (
  count_over_time(
		{k8s_cluster_name=~"$cluster", k8s_container_name="server"} | json | msg!="" | msg!~".*TotalAlloc.*" | msg!~".*argocd-notifications.*" |= "$filter"
    [$__auto]
  )
)
